diff --git a/mail/modules/QuoteSanitizer.sys.mjs b/mail/modules/QuoteSanitizer.sys.mjs
index 5f967fcbf6f..7e0befed48b 100644
--- a/mail/modules/QuoteSanitizer.sys.mjs
+++ b/mail/modules/QuoteSanitizer.sys.mjs
@@ -2,23 +2,29 @@
